-- READ ONLY. One JSON cell. No roster names or Auth/admin rows.
select jsonb_build_object(
 'tournaments',coalesce((select jsonb_agg(jsonb_build_object('id',id,'schemaVersion',schema_version,'revision',revision,'targets',set_rules)) from public.tournaments),'[]'::jsonb),
 'legacy_matches_requiring_review',coalesce((select jsonb_agg(jsonb_build_object('tournamentId',m.tournament_id,'matchId',m.id,'status',m.status)) from public.matches m where m.status<>'scheduled' or m.rules_snapshot is not null or exists(select 1 from public.match_sets s where s.tournament_id=m.tournament_id and s.match_id=m.id and(s.home_score is not null or s.away_score is not null))or exists(select 1 from public.match_rounds r where r.tournament_id=m.tournament_id and r.match_id=m.id and r.winner_side is not null)),'[]'::jsonb),
 'roster_counts',coalesce((select jsonb_agg(to_jsonb(counts))from(select tournament_id,team_id,count(*) players from public.players group by tournament_id,team_id)counts),'[]'::jsonb),
 'functions',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'definition',pg_get_functiondef(p.oid),'securityDefiner',p.prosecdef,'configuration',p.proconfig,'anonExecute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticatedExecute',has_function_privilege('authenticated',p.oid,'EXECUTE')))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.prokind='f' and ((n.nspname='volleyball_private'and p.proname in('score_result','round_result','group_rank','validate_snapshot','check_result_sport'))or(n.nspname='public'and p.proname in('save_tournament','get_public_tournament','get_competition_format_version')))),'[]'::jsonb),
 'constraints',coalesce((select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)))from pg_constraint where conrelid in('public.tournaments'::regclass,'public.match_sets'::regclass,'public.match_rounds'::regclass,'public.players'::regclass)),'[]'::jsonb)
) as three_set_preflight;
